"""`.env.production.example` generated from ``Settings`` so documentation cannot drift (ADR-016)."""

from __future__ import annotations

from forma.core.settings import SECRET_FIELDS, Settings

HEADER = """\
# FORMA production configuration — generated by `forma config example` from forma.core.settings.Settings.
# Every variable, its default and a one-line explanation. Copy to .env.production and fill in the
# secrets (marked SECRET). Do not edit by hand: `forma config example --check .env.production.example`
# runs in CI and fails when this file is out of date.
"""


def render_env_example() -> str:
    lines = [HEADER]
    for env, default, desc in Settings.describe():
        name = env.removeprefix("FORMA_").lower()
        tag = "  [SECRET]" if name in SECRET_FIELDS else ""
        lines.append(f"# {desc}{tag}")
        if name in SECRET_FIELDS:
            lines.append(f"{env}=")
        else:
            lines.append(f"{env}={default}")
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"
